import{_ as t,o as a,c as i,ae as s}from"./chunks/framework.C4zpkcTP.js";const k=JSON.parse('{"title":"Installation","description":"Install Laravel Refresh Token, generate the RSA keys and run the migration.","frontmatter":{"title":"Installation","description":"Install Laravel Refresh Token, generate the RSA keys and run the migration."},"headers":[],"relativePath":"laravel-refresh-token/installation.md","filePath":"laravel-refresh-token/installation.md"}'),n={name:"laravel-refresh-token/installation.md"};function o(r,e,h,d,l,p){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> require</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> laranex/laravel-refresh-token</span></span></code></pre></div><p>The service provider and the <code>RefreshToken</code> facade alias are registered automatically.</p><h2 id="keys" tabindex="-1">Keys <a class="header-anchor" href="#keys" aria-label="Permalink to &quot;Keys&quot;">​</a></h2><p>Generate an RSA key pair for signing refresh tokens. The command writes <code>refresh-token-private.key</code> (with <code>0600</code> permissions) and <code>refresh-token-public.key</code> to the key path (<code>storage/</code> by default, see <a href="/laravel-refresh-token/configuration.html">Configuration</a>).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> refresh-token:keys</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Option</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>--force</code></td><td></td><td>Overwrite keys that already exist</td></tr><tr><td><code>--length</code></td><td><code>4096</code></td><td>Length of the private key in bits (at least <code>2048</code>)</td></tr></tbody></table><p>The command creates the key directory if it does not exist. If the directory or either key file cannot be written it prints the path and exits with status <code>1</code>, so a deploy script fails instead of continuing without keys.</p><p>In production you can set the PEM contents in <code>REFRESH_TOKEN_PRIVATE_KEY</code> and <code>REFRESH_TOKEN_PUBLIC_KEY</code> instead of shipping key files. Literal <code>\\n</code> sequences are expanded to newlines.</p><p>When neither the environment variable nor the key file is available, issuing or verifying a token throws <code>Laranex\\RefreshToken\\Exceptions\\MissingKeyException</code>, which names the file it expected.</p><h2 id="migration" tabindex="-1">Migration <a class="header-anchor" href="#migration" aria-label="Permalink to &quot;Migration&quot;">​</a></h2><p>The package loads its migration automatically. Run it to create the <code>laravel_refresh_tokens</code> table (the name is configurable, see <a href="/laravel-refresh-token/configuration.html">Configuration</a>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span></span></code></pre></div><p>To customize the migration, publish it first:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vendor:publish</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tag=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;refresh-token-migrations&quot;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Tag</th><th>Publishes</th></tr></thead><tbody><tr><td><code>refresh-token-config</code></td><td><code>config/refresh-token.php</code></td></tr><tr><td><code>refresh-token-migrations</code></td><td><code>database/migrations/*_create_laravel_refresh_tokens_table.php</code></td></tr><tr><td><code>refresh-token</code></td><td>Both</td></tr></tbody></table>',16)])])}const g=t(n,[["render",o]]);export{k as __pageData,g as default};
